import { prisma } from "@powerchain/database";
import { requireSession } from "../../../../../lib/current-session";
export const dynamic="force-dynamic";
export async function GET(){try{const session=await requireSession();const membership=session.user.memberships[0];if(!membership)throw new Error();const since=new Date();since.setUTCDate(1);const grouped=await prisma.usageEvent.groupBy({by:["metric"],where:{organizationId:membership.organizationId,occurredAt:{gte:since}},_sum:{quantity:true}});return Response.json({data:grouped.map((x: (typeof grouped)[number])=>({metric:x.metric,quantity:x._sum.quantity??0})),meta:{requestId:crypto.randomUUID()}},{headers:{"cache-control":"no-store"}})}catch{return Response.json({error:{code:"UNAUTHENTICATED",message:"Sign in required.",requestId:crypto.randomUUID()}},{status:401})}}
